WITH session_totals AS (SELECT session_id, MAX(duration_sec) AS max_duration_sec, AVG(duration_sec) AS avg_duration_sec FROM web_events WHERE event_time >= '2023-07-21' GROUP BY session_id) SELECT sessions.browser, sessions.started_at, session_totals.max_duration_sec, session_totals.avg_duration_sec FROM sessions INNER JOIN session_totals ON sessions.id = session_totals.session_id ORDER BY started_at ASC, avg_duration_sec DESC;
